{
  "name": "builder_all_pairs_gapthr_w_001",
  "intuition": "Filter out near-ties by requiring a minimum objective improvement and weight remaining pairs by the objective gap, emphasizing clearer preferences and reducing noisy training signal.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # lower objective is better\n    gap_threshold = extra.get('gap_threshold', 0.0)\n    # gap[b,i,j] = objective[j] - objective[i]; positive means i better than j\n    gap = objective[:, None, :] - objective[:, :, None]\n    mask = gap > gap_threshold\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    weight = gap[b_idx, winner_idx, loser_idx].clamp_min(0.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gapthr_w', 'gap_threshold': float(gap_threshold)})\n"
}

