  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n\n    hyper = (extra.get('hyperparams', {}) if (extra is not None) else {})\n    alpha = extra.get('alpha', hyper.get('alpha', 1.0)) if (extra is not None) else hyper.get('alpha', 1.0)\n    scale = hyper.get('scale', 1.2)\n    margin = hyper.get('margin', 0.05)\n    cmin = hyper.get('clamp_min', -20.0)\n    cmax = hyper.get('clamp_max', 20.0)\n    eps = hyper.get('eps', 1e-8)\n\n    # Stable pairwise logistic loss with a small margin.\n    x = alpha * scale * (lpw - lpl) - margin\n    x = ops.clamp(x, cmin, cmax)\n    per = -ops.logsigmoid(x)\n\n    weight = batch.get('weight', None)\n    if weight is None:\n        return per.mean()\n\n    # Enforce non-negative weights and normalize to keep loss scale stable.\n    w = ops.clamp(weight, 0.0, 1e9)\n    denom = ops.clamp(w.sum(), eps, 1e18)\n    return (per * w).sum() / denom",
